import type { I18nText } from './explorer-types';
import type {
  MissionPropKind,
  MissionSceneEntity,
  MissionSceneFlow,
  MissionSetting,
  MissionVisualDefinition,
  MissionVisualFrame,
} from './mission-stage-types';

const text = (zh: string, en: string): I18nText => ({ zh, en });

const entity = (
  id: string,
  kind: MissionPropKind,
  x: number,
  y: number,
  options: Pick<MissionSceneEntity, 'label' | 'opacity' | 'pose' | 'scale'> = {},
): MissionSceneEntity => ({ id, kind, x, y, ...options });

const flow = (
  id: string,
  from: string,
  to: string,
  kind: MissionSceneFlow['kind'],
): MissionSceneFlow => ({ id, from, to, kind });

const frame = (
  descriptionZh: string,
  descriptionEn: string,
  entities: readonly MissionSceneEntity[],
  flows: readonly MissionSceneFlow[] = [],
): MissionVisualFrame => ({ description: text(descriptionZh, descriptionEn), entities, flows });

const mission = (
  setting: MissionSetting,
  titleZh: string,
  titleEn: string,
  initial: MissionVisualFrame,
  a: MissionVisualFrame,
  b: MissionVisualFrame,
): MissionVisualDefinition => ({ setting, title: text(titleZh, titleEn), initial, choices: { a, b } });

